		using (BufferedReader r = new BufferedReader(new FileReader(sshPublicKeyFile)))
{
			string line;
			while ((line = r.readLine()) != null) {
				if (!line.startsWith("ssh-")) {
					continue;
				}
				keyLine = line;
				break;
			}
		}

		if (keyLine != null) {
			string[] part = keyLine.split("\\s+");
